// Get data from both sheets
const gaItems = $input.first().json;
const msItems = $input.last().json;

// List names to include from GA
const allowedListNames = [
  'bad tech',
  'PC, invest, sensitive content, sites, logins, misc',
  'skill-seekers, deals, errors',
  'too short',
  'competitors',
  'too short - sql perf',
  'SQL Deployments',
  'Irrelevant info queries'
];

// Helper function to format keyword with match type
function formatKeyword(keyword, matchType) {
  if (matchType === 'EXACT') {
    return `[${keyword}]`;
  } else if (matchType === 'PHRASE') {
    return `"${keyword}"`;
  }
  // BROAD match (no special formatting)
  return keyword;
}

// Helper function to create unique key for comparison
function makeKey(keyword, matchType) {
  return `${keyword}|||${matchType}`;
}

// Filter and process GA items
const gaFiltered = gaItems.filter(item => 
  allowedListNames.includes(item.list_name)
);

// Create sets for comparison (keyword + match_type)
const gaKeySet = new Set(
  gaFiltered.map(item => makeKey(item.keyword, item.match_type))
);

const msKeySet = new Set(
  msItems.map(item => makeKey(item.keyword, item.match_type))
);

// Find keywords to add to MS (in GA but not in MS)
const addToMS = [];
for (const item of gaFiltered) {
  const key = makeKey(item.keyword, item.match_type);
  if (!msKeySet.has(key)) {
    addToMS.push({
      keyword: item.keyword,
      match_type: item.match_type
    });
  }
}

// Find keywords to add to GA (in MS but not in GA)
const addToGA = [];
for (const item of msItems) {
  const key = makeKey(item.keyword, item.match_type);
  if (!gaKeySet.has(key)) {
    addToGA.push({
      keyword: item.keyword,
      match_type: item.match_type
    });
  }
}

// Build output rows
const outputRows = [];
const maxRows = Math.max(addToGA.length, addToMS.length);

for (let i = 0; i < maxRows; i++) {
  const row = {
    add_to_GA: '',
    add_to_MS: ''
  };

  if (i < addToGA.length) {
    row.add_to_GA = formatKeyword(addToGA[i].keyword, addToGA[i].match_type);
  }

  if (i < addToMS.length) {
    row.add_to_MS = formatKeyword(addToMS[i].keyword, addToMS[i].match_type);
  }

  outputRows.push(row);
}

// Return the output rows
return outputRows.map(row => ({ json: row }));
